#include "BookMessageDiagnosticsHook.h"
#include "../Util/Logger.h"
#include "../../include/HookCrashers/Public/Globals.h"
#include <windows.h>
#include <detours.h>
#include <cstdint>
#include <intrin.h>

namespace HookCrashers::Save { namespace { constexpr uintptr_t kShowBookMessageRva = 0x12DAA0; constexpr int kMaxStackFrames = 16; using ShowBookMessageFn = int(__thiscall*)(uint32_t* self, int16_t messageGroup, int16_t returnMenuId); ShowBookMessageFn g_originalShowBookMessage = nullptr;  int __fastcall DetouredShowBookMessage(uint32_t* self, void*, int16_t messageGroup, int16_t returnMenuId) {     const uintptr_t callerRet = reinterpret_cast<uintptr_t>(_ReturnAddress());     const uint16_t subreason = self ? *reinterpret_cast<uint16_t*>(reinterpret_cast<uint8_t*>(self) + 0x34) : 0xFFFF;     const uint16_t oldGroup = self ? *reinterpret_cast<uint16_t*>(reinterpret_cast<uint8_t*>(self) + 0x36) : 0xFFFF;     const uint16_t activeMenuId = self ? *reinterpret_cast<uint16_t*>(reinterpret_cast<uint8_t*>(self) + 0x3C) : 0xFFFF;     const uint32_t currentMenu = self ? *reinterpret_cast<uint32_t*>(reinterpret_cast<uint8_t*>(self) + 0x38) : 0;     const uint32_t menuTable = self ? *reinterpret_cast<uint32_t*>(reinterpret_cast<uint8_t*>(self) + 0x40) : 0;     auto log = Util::Logger::Instance().Get();     log->info("[BookMessage] ShowBookMessage self=0x{:X} a2={} a3={} subreason={} old_group={} active_id={} current=0x{:X} table=0x{:X} caller_ret=0x{:X} caller_rva=0x{:X}.", reinterpret_cast<uintptr_t>(self), messageGroup, returnMenuId, subreason, oldGroup, activeMenuId, currentMenu, menuTable, callerRet, callerRet >= g_moduleBase ? callerRet - g_moduleBase : 0);     void* frames[kMaxStackFrames]{};     const USHORT count = CaptureStackBackTrace(0, kMaxStackFrames, frames, nullptr);     for (USHORT i = 0; i < count; ++i) {         const uintptr_t address = reinterpret_cast<uintptr_t>(frames[i]);         log->info("[BookMessage] stack[{}]=0x{:X} rva=0x{:X}.", i, address, address >= g_moduleBase ? address - g_moduleBase : 0);     }     return g_originalShowBookMessage(self, messageGroup, returnMenuId); }  }  bool SetupBookMessageDiagnosticsHook() {     g_originalShowBookMessage = reinterpret_cast<ShowBookMessageFn>(g_moduleBase + kShowBookMessageRva);     Util::Logger::Instance().Get()->info("[BookMessage] Installing hook | name=ShowBookMessage | RVA=0x{:X} | VA=0x{:X}.", kShowBookMessageRva, reinterpret_cast<uintptr_t>(g_originalShowBookMessage));     DetourTransactionBegin();     DetourUpdateThread(GetCurrentThread());     const LONG attachResult = DetourAttach(&(PVOID&)g_originalShowBookMessage, DetouredShowBookMessage);     if (attachResult != NO_ERROR) {         Util::Logger::Instance().Get()->error("[BookMessage] ShowBookMessage DetourAttach failed: {}.", attachResult);         DetourTransactionAbort();         return false;     }     const LONG commitResult = DetourTransactionCommit();     if (commitResult != NO_ERROR) {         Util::Logger::Instance().Get()->error("[BookMessage] ShowBookMessage DetourTransactionCommit failed: {}.", commitResult);         return false;     }     Util::Logger::Instance().Get()->info("[BookMessage] ShowBookMessage diagnostics hook attached successfully.");     return true; }  }
